static const z_t5612_t _zag1729 = { { .data = "clz64", .size = 5 }, { .length = 1, .data = _zag1728 }, { .length = 0, .data = NULL }, { .data = "#if defined(_MSC_VER) && !defined(__clang__)\n#include <intrin.h>\nstatic inline int z_clz64(uint64_t v) {\n    unsigned long i;\n    _BitScanReverse64(&i, v);\n    return 63 - (int)i;\n}\n#else\n#define z_clz64(v) __builtin_clzll(v)\n#endif", .size = 232 } };
