static const z_t5797_t _zag2116 = { { .data = "", .size = 0 }, { .length = 0, .data = NULL }, { .data = "/* The entry IS the projection: `entries` is dense, so a borrowed entry is a\n   plain `&entries[idx]` and the cursor is an index test rather than a scan for\n   the next live one. Insertion order, and nothing can perforate it. */\n/*@@entrytype@@*/typedef z_@@NAME@@_entry_t z_@@IDMAPENTRY@@_t;\n\ntypedef struct {\n    z_@@NAME@@_t* m;\n    uint32_t idx;\n} z_@@IDMAPITEMITER@@_t;\n\nstatic z_@@OPTIONVIEW_ENTRY@@_t z_@@IDMAPITEMITER@@_call(z_@@IDMAPITEMITER@@_t* _it);\nstatic z_@@OPTIONVIEW_ENTRY@@_t z_@@IDMAPITEMITER@@_call(z_@@IDMAPITEMITER@@_t* _it) {\n    z_@@OPTIONVIEW_ENTRY@@_t _out = {0};\n    if (_it->idx < _it->m->length) {\n        _out.tag = @@OPTIONVIEW_ENTRY_SOME@@;\n        _out.data = &_it->m->entries[_it->idx];\n        _it->idx++;\n        return _out;\n    }\n    _out.tag = @@OPTIONVIEW_ENTRY_NONE@@;\n    return _out;\n}\n\nstatic z_@@IDMAPITEMITER@@_t z_@@NAME@@_iterateItems(const z_@@NAME@@_t* _this);\nstatic z_@@IDMAPITEMITER@@_t z_@@NAME@@_iterateItems(const z_@@NAME@@_t* _this) {\n    z_@@IDMAPITEMITER@@_t _it = {0};\n    /* the same const stop as `get` and z_Set's `iterate`: OptionView's payload\n       is a bare void*, so const cannot propagate into it */\n    _it.m = (z_@@NAME@@_t*)_this;\n    _it.idx = 0;\n    return _it;\n}", .size = 1239 } };
