static const z_t5797_t _zag2119 = { { .data = "", .size = 0 }, { .length = 0, .data = NULL }, { .data = "/* getMut hands back a pointer INTO the entry where the value family's `get`\n   copies out, so an update writes the entry in place instead of going through\n   `set`. One emitted function for both families: what differs is the declared\n   return, exactly as ListRef.get (a view) and ListVal.get (a copy) already\n   differ while sharing one getMut.\n\n   Its own template, for the reason IdMapIter is separate: a mono whose\n   `getMut` never resolved must still emit its container, and a template read\n   by a seed that cannot fill its holes writes them into the C verbatim. */\n\nstatic z_@@OPTIONMUT_V@@_t z_@@NAME@@_getMut(z_@@NAME@@_t* _this, @@KEY_T@@ _key);\nstatic z_@@OPTIONMUT_V@@_t z_@@NAME@@_getMut(z_@@NAME@@_t* _this, @@KEY_T@@ _key) {\n    z_@@OPTIONMUT_V@@_t _r = {0};\n    int64_t idx = z_@@NAME@@_find(_this, _key, NULL);\n    if (idx >= 0) {\n        _r.tag = @@OPTIONMUT_V_SOME@@;\n        _r.data = &_this->entries[idx].value;\n    } else {\n        _r.tag = @@OPTIONMUT_V_NONE@@;\n        _r.data = NULL;\n    }\n    return _r;\n}", .size = 1033 } };
